SET NAMES utf8mb4;

INSERT INTO `service`
  (`token`, `service_name`, `service_img`, `short_description`, `description`,
   `card1_title`, `card1_description`, `card2_title`, `card2_description`,
   `process_steps`, `faqs`, `status`, `delete_status`, `created_by`)
SELECT
  'lithium-ion-battery-service',
  'Lithium-Ion Battery Initialization, Service & Maintenance',
  'themes/images/service-image-12.jpg',
  'Professional lithium-ion battery initialization, servicing and maintenance in Coimbatore - condition checks, BMS diagnostics and charging system checks for electric vehicles, energy storage and backup systems, according to manufacturer specifications. Monday to Saturday, 9AM to 10PM.',
  'Lithium-ion batteries are widely used in electric vehicles, energy storage systems, backup power solutions and various electronic applications. Proper initialization, regular inspection and preventive maintenance support battery performance, reliability and safe operation. Kiara Battery Clinic offers lithium-ion battery initialization, service and maintenance in Coimbatore and nearby areas including Ooty, Kotagiri, Pollachi and Tiruppur, Monday to Saturday, 9AM to 10PM.\n\nOur service addresses battery setup requirements, charging concerns, connection issues and general battery health checks. Depending on the battery type and application, it may include battery condition assessment, terminal and connector inspection, battery management system (BMS) diagnostics, charging system checks and maintenance recommendations.\n\nWhether your lithium-ion battery is used in an electric vehicle, commercial equipment or a compatible energy storage application, our approach focuses on identifying potential issues and recommending suitable service procedures. Initialization and configuration are carried out where applicable, following the battery manufacturer''s specifications and system requirements.\n\nRegular battery inspections help identify early signs of deterioration, charging irregularities and connection problems. Call or WhatsApp +91 90038 11107 to discuss your lithium-ion battery service requirements and find the right maintenance solution for your battery system.',
  'Lithium-Ion Battery Initialization & Diagnostics',
  'Prepare compatible lithium-ion battery systems for operation through the required initialization, configuration and diagnostic procedures. Our service helps assess battery status, review BMS-related information and identify potential setup or performance issues according to manufacturer guidelines.',
  'Battery Servicing & Preventive Maintenance',
  'Support battery reliability with routine condition checks, connector inspection, charging system assessment and maintenance recommendations. Our service helps identify developing issues and determine whether further diagnostics, approved repairs or battery replacement may be necessary.',
  'Service request - contact our team and describe your lithium-ion battery service requirements.\nBattery details - share the battery type, voltage, capacity, manufacturer, model and application, if available.\nInitial inspection - inspect the battery externally for visible damage, connector issues, corrosion, swelling or other warning signs.\nBattery diagnostics - assess available battery status information, charging behaviour and BMS diagnostic data where supported.\nInitialization or configuration - perform applicable initialization or configuration procedures according to the manufacturer specifications.\nMaintenance and service - carry out approved maintenance procedures and address identified serviceable issues where appropriate.\nFinal assessment - review the battery condition, document findings and recommend further testing, approved repair or replacement if required.',
  '[{"question":"What is lithium-ion battery initialization?","answer":"Lithium-ion battery initialization is the required setup or configuration of a compatible battery system before use or after certain service procedures. The exact process depends on the battery design, BMS, connected equipment and manufacturer instructions."},{"question":"What does lithium-ion battery servicing include?","answer":"Depending on the battery system, servicing may include visual inspection, diagnostic checks, connector inspection, BMS status review and charging system assessment. The available services depend on the battery model and the manufacturer approved procedures."},{"question":"How often should a lithium-ion battery be maintained?","answer":"Maintenance frequency depends on the battery application, operating environment, usage patterns and manufacturer recommendations. Regular condition checks help identify potential problems before they affect normal operation."},{"question":"What are the common signs of lithium-ion battery problems?","answer":"Common warning signs include reduced operating time, unexpected shutdowns, charging difficulties, unusual error codes, overheating or visible physical damage. A qualified technician should inspect the battery if any of these symptoms occur."},{"question":"Can a lithium-ion battery be repaired instead of replaced?","answer":"Some battery-related issues may be serviceable, depending on the battery design and manufacturer requirements. However, damaged cells or internal safety faults may need specialist assessment or battery replacement rather than repair."},{"question":"What is a Battery Management System (BMS)?","answer":"A Battery Management System monitors and manages important battery operating conditions such as voltage, temperature and charging or discharging limits. Depending on the design, it may also provide protection functions and diagnostic information."},{"question":"Can lithium-ion batteries be serviced while connected to equipment?","answer":"It depends on the equipment and battery design. Some inspections may be possible while the battery is installed, but electrical work or internal servicing may need isolation by a qualified technician according to manufacturer safety instructions."},{"question":"What should I do if my lithium-ion battery becomes swollen or overheats?","answer":"Stop using and charging the battery if it is safe to do so, keep it away from the affected equipment and follow the manufacturer emergency guidance. Do not open, puncture or attempt to repair a swollen or overheating battery. Seek help from a qualified battery service professional."},{"question":"Which information is required to request lithium-ion battery maintenance?","answer":"Share the battery manufacturer, model, voltage, capacity, application and a description of the issue. Photos of the external label or any displayed error codes also help our team assess your requirement."},{"question":"Do you provide lithium-ion battery service in Coimbatore and what are your hours?","answer":"Yes. Kiara Battery Clinic provides lithium-ion battery initialization, service and maintenance in Coimbatore (Tatabad, Gandhipuram, RS Puram, Peelamedu, Saravanampatti) and, on request, Ooty, Kotagiri, Pollachi and Tiruppur. Service hours are Monday to Saturday, 9AM to 10PM; call or WhatsApp +91 90038 11107."}]',
  'active',
  0,
  0
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `service` WHERE `token` = 'lithium-ion-battery-service');
